// Emits the admin TypeScript artifacts under
//   apps/admin/src/lib/generated/
//
// Files: types.ts, attr-keys.ts, catalog.ts, labels.ts, format.ts
//
// The admin app is self-contained: it owns its own PropertyType / PropertyAttributes
// / AttrKey types (no @/ aliases). These generated files mirror the hand-written
// propertyAttributes.ts so that migration (step 1.4b) is a drop-in replacement of
// the catalog/labels/format/data portions. The hand-written propertyAttributes.ts
// remains untouched here.
//
// What stays hand-written (UI logic that is not derivable from catalog.json):
//   - the public re-export barrel (if any) — not present today.
// Everything else (catalog, labels, format functions, isPropertyType) is generated.

import {
  TYPE_ORDER,
  TYPE_ALIASES,
  fieldsFor,
  enumOptionKeys,
  allFieldKeys,
  mergedEnumOptions,
} from './model.mjs';

const HEADER = `// Code generated by tools/property-attributes/generate.mjs from catalog.json. DO NOT EDIT.`;

// ----- types.ts -----
export function emitTypes(catalog) {
  void catalog;
  return `${HEADER}

// Self-contained types for the admin app (no external aliases).

export type PropertyType =
  | 'apartment'
  | 'room'
  | 'apartments'
  | 'studio'
  | 'house'
  | 'commercial'
  | 'office'
  | 'warehouse'
  | 'garage'
  | 'parking'
  | 'land';

export type PropertyAttributes = Readonly<Record<string, string | number>>;
`;
}

// ----- attr-keys.ts -----
export function emitAttrKeys(catalog) {
  const keys = allFieldKeys(catalog);
  const union = keys.map((k) => `  | ${JSON.stringify(k)}`).join('\n');
  const arr = keys.map((k) => `  ${JSON.stringify(k)},`).join('\n');
  return `${HEADER}

export type AttrKey =
${union};

export const attrKeys: readonly AttrKey[] = [
${arr}
] as const;
`;
}

// ----- catalog.ts -----
function groupLit(group) {
  return group === null ? 'null' : JSON.stringify(group);
}

function emitFieldList(typeKey, catalog) {
  const entries = fieldsFor(catalog, typeKey);
  const lines = entries.map(({ key, def }) => {
    switch (def.kind) {
      case 'enum': {
        const opts = enumOptionKeys(def).map((o) => JSON.stringify(o)).join(', ');
        return `  { key: ${JSON.stringify(key)}, kind: 'enum', options: [${opts}], group: ${groupLit(def.group)} },`;
      }
      case 'number':
        return `  { key: ${JSON.stringify(key)}, kind: 'number', unit: ${JSON.stringify(def.unit)}, min: ${def.min}, max: ${def.max}, decimals: ${def.decimals}, group: ${groupLit(def.group)} },`;
      case 'integer': {
        const maxExpr = def.yearBuiltMaxDynamic === true ? 'yearBuiltMax' : JSON.stringify(def.max);
        return `  { key: ${JSON.stringify(key)}, kind: 'integer', min: ${def.min}, max: ${maxExpr}, group: ${groupLit(def.group)} },`;
      }
      case 'string':
        return `  { key: ${JSON.stringify(key)}, kind: 'string', maxLen: ${def.maxLen}, group: ${groupLit(def.group)} },`;
      default:
        throw new Error(`unknown kind for field ${key}: ${def.kind}`);
    }
  });
  return lines.join('\n');
}

export function emitCatalog(catalog) {
  const primaries = TYPE_ORDER.filter((t) => !TYPE_ALIASES[t]);
  const listBlocks = primaries.map((t) => {
    return `const ${t}Fields: AttrFieldList = [
${emitFieldList(t, catalog)}
];`;
  });

  const catalogEntries = TYPE_ORDER.map((t) => {
    if (TYPE_ALIASES[t]) {
      const primary = TYPE_ALIASES[t];
      return `  ${JSON.stringify(t)}: ${primary}Fields,`;
    }
    return `  ${JSON.stringify(t)}: ${t}Fields,`;
  }).join('\n');

  return `${HEADER}

import type { PropertyType } from './types';
import type { AttrKey } from './attr-keys';

export type AttrGroup = 'about_object' | 'about_building' | 'about_house' | 'about_land';

export type AttrField =
  | { readonly key: AttrKey; readonly kind: 'enum'; readonly options: readonly string[]; readonly group: AttrGroup | null }
  | { readonly key: AttrKey; readonly kind: 'number'; readonly unit: 'м²' | 'сотки' | 'м'; readonly min: number; readonly max: number; readonly decimals: number; readonly group: AttrGroup | null }
  | { readonly key: AttrKey; readonly kind: 'integer'; readonly min: number; readonly max: number; readonly group: AttrGroup | null }
  | { readonly key: AttrKey; readonly kind: 'string'; readonly maxLen: number; readonly group: AttrGroup | null };

export type AttrFieldList = readonly AttrField[];

const yearBuiltMax = new Date().getFullYear() + 5;

${listBlocks.join('\n\n')}

export const catalog: Readonly<Record<PropertyType, AttrFieldList>> = {
${catalogEntries}
};

export const groupLabels: Readonly<Record<AttrGroup, string>> = {
  about_object: 'О квартире',
  about_building: 'О доме',
  about_house: 'О доме',
  about_land: 'Об участке',
};

export function fieldsForType(type: PropertyType): AttrFieldList {
  return catalog[type];
}

export function findField(type: PropertyType, key: AttrKey): AttrField | undefined {
  return fieldsForType(type).find((field) => field.key === key);
}

export function isPropertyType(value: unknown): value is PropertyType {
  return typeof value === 'string' && value in catalog;
}
`;
}

// ----- labels.ts -----
export function emitLabels(catalog) {
  const keys = allFieldKeys(catalog);
  const fieldLabelsMap = keys
    .map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(findFieldLabel(catalog, k))},`)
    .join('\n');

  const enumMap = mergedEnumOptions(catalog);
  const enumBlocks = [];
  for (const fkey of keys) {
    const opts = enumMap.get(fkey);
    if (!opts || opts.size === 0) continue;
    const optLines = [...opts.entries()]
      .map(([oKey, oLabel]) => `    ${JSON.stringify(oKey)}: ${JSON.stringify(oLabel)},`)
      .join('\n');
    enumBlocks.push(`  ${JSON.stringify(fkey)}: {
${optLines}
  },`);
  }

  return `${HEADER}

import type { AttrKey } from './attr-keys';

export const fieldLabels: Readonly<Record<AttrKey, string>> = {
${fieldLabelsMap}
};

export const enumLabels: Readonly<
  Partial<Record<AttrKey, Readonly<Record<string, string>>>>
> = {
${enumBlocks.join('\n')}
};
`;
}

function findFieldLabel(catalog, fieldKey) {
  for (const t of TYPE_ORDER) {
    const real = TYPE_ALIASES[t] ?? t;
    const f = catalog.types[real].fields[fieldKey];
    if (f) return f.label;
  }
  throw new Error(`field ${fieldKey} not found in any type`);
}

// ----- format.ts -----
// Reproduces the hand-written format functions: formatAttributeValue and
// formatAttributesForCardGrouped (including the floor "X из Y" rule and the
// hide-floors_total-when-both-present grouping behaviour). Driven entirely by
// catalog + labels + groupLabels.
export function emitFormat(catalog) {
  void catalog;
  return `${HEADER}

import type { PropertyType, PropertyAttributes } from './types';
import type { AttrKey } from './attr-keys';
import { fieldsForType, groupLabels, type AttrGroup } from './catalog';
import { fieldLabels, enumLabels } from './labels';

export function formatAttributeValue(
  type: PropertyType,
  key: AttrKey,
  value: string | number,
  attrs: PropertyAttributes,
): string {
  const def = fieldsForType(type).find((field) => field.key === key);

  if (!def) {
    return String(value);
  }

  if (def.kind === 'enum') {
    return enumLabels[key]?.[String(value)] ?? String(value);
  }

  if (def.kind === 'number') {
    const num = typeof value === 'number' ? value : Number(value);
    const formatted = Number.isFinite(num)
      ? num.toFixed(def.decimals).replace('.', ',')
      : String(value);
    return \`\${formatted} \${def.unit}\`;
  }

  if (def.kind === 'integer') {
    if (key === 'floor') {
      const floorsTotal = attrs.floors_total;
      if (floorsTotal !== undefined && (typeof floorsTotal === 'string' || typeof floorsTotal === 'number')) {
        return \`\${value} из \${floorsTotal}\`;
      }
    }
    return String(value);
  }

  // def.kind === 'string'
  return String(value);
}

function isFilled(value: unknown): boolean {
  if (value === undefined) return false;
  if (value === null) return false;
  if (typeof value === 'string' && value === '') return false;
  return true;
}

export type AttrCardItem = { readonly label: string; readonly value: string };

export type AttrCardGroup = {
  readonly group: AttrGroup | null;
  readonly label: string | null;
  readonly items: readonly AttrCardItem[];
};

export function formatAttributesForCardGrouped(
  type: PropertyType,
  attrs: PropertyAttributes,
): AttrCardGroup[] {
  const hasFloor = isFilled(attrs.floor);
  const hasFloorsTotal = isFilled(attrs.floors_total);
  const hideFloorsTotal = hasFloor && hasFloorsTotal;

  type MutableGroup = { group: AttrGroup | null; label: string | null; items: AttrCardItem[] };
  const groups: MutableGroup[] = [];
  let currentGroup: AttrGroup | null | undefined;

  for (const field of fieldsForType(type)) {
    if (field.key === 'floors_total' && hideFloorsTotal) continue;

    const raw = attrs[field.key];
    if (!isFilled(raw)) continue;
    if (typeof raw !== 'string' && typeof raw !== 'number') continue;

    if (currentGroup !== field.group) {
      currentGroup = field.group;
      groups.push({
        group: field.group,
        label: field.group === null ? null : groupLabels[field.group],
        items: [],
      });
    }

    groups[groups.length - 1]?.items.push({
      label: fieldLabels[field.key],
      value: formatAttributeValue(type, field.key, raw, attrs),
    });
  }

  return groups;
}
`;
}
